            f"Local mapped-stage review {'"'"'"'"'"'"'"'"'passed'"'"'"'"'"'"'"'"' if result['"'"'"'"'"'"'"'"'pass'"'"'"'"'"'"'"'"'] else '"'"'"'"'"'"'"'"'failed'"'"'"'"'"'"'"'"'} with {len(errors)} errors and {len(warnings)} warnings.",
